mapper.select:
SELECT al.id ,al.fund_code ,COALESCE(al.fund_name, al.fund_short_name) AS fundName ,al.security_type ,dst.security_type_name ,al.adjust_type ,al.adjust_mode ,al.target_pool_id ,p.pool_name AS targetPoolPath ,al.adjust_batch_no ,al.audit_status ,al.adjuster_name ,al.submit_time FROM ip_adjust_log_fund al LEFT JOIN ip_investment_pool p ON p.id = al.target_pool_id AND p.is_deleted = 0 INNER JOIN dict_security_type dst ON dst.security_type = al.security_type AND dst.category_type = 'fund' AND dst.is_deleted = 0
al.is_deleted = 0
AND al.target_pool_id IN
#{poolId}
AND al.fund_code LIKE CONCAT('%', #{fundCode}, '%')
AND (al.fund_name LIKE CONCAT('%', #{fundName}, '%') OR al.fund_short_name LIKE CONCAT('%', #{fundName}, '%'))
AND al.security_type = #{securityType}
AND al.submit_time >= #{adjustTimeStart}
AND al.submit_time <= CONCAT(#{adjustTimeEnd}, ' 23:59:59')
AND al.adjuster_name LIKE CONCAT('%', #{adjusterName}, '%')
AND al.adjust_mode = #{adjustMode}
AND al.audit_status = #{auditStatus}
ORDER BY al.submit_time DESC ,al.adjust_batch_no DESC ,al.id DESC
